// POST /api/v1/sites/{siteId}/media/{mediaId}/generate-variants
//
// Responsive WebP/AVIF variants (320 / 640 / 1024 / 1920 and the original
// width) are generated by the organization's build engine during the next
// publication, from the item in organization storage. The portal no longer
// transcodes images; this endpoint stays for API compatibility and reports
// what will happen to the item.

import type { APIRoute } from 'astro';
import { apiError, apiResponse, requireApiKey } from '../../../../../../../lib/api-auth';
import { getStore } from '../../../../../../../lib/datastore';
import { paths } from '@typeroll/shared';
import type { Media } from '@typeroll/shared';

const PROCESSABLE_MIME = new Set(['image/jpeg', 'image/png', 'image/webp', 'image/avif', 'image/gif']);

export const POST: APIRoute = async ({ request, params }) => {
  const guard = await requireApiKey(request, params.siteId);
  if (!guard.ok) return guard.response;
  const ctx = guard.value;
  if (ctx.permission === 'read') return apiError('Media changes require write permission.', 403);
  const mediaId = params.mediaId;
  if (!mediaId) return apiError('Missing mediaId');

  const media = await getStore().getDoc<Media>(`${paths.media(ctx.orgId, ctx.siteId)}/${mediaId}`);
  if (!media) return apiError('Not found', 404);
  // A non-image (PDF etc.) is a 200 so an agent's "sweep all media" loop continues.
  if (!media.mime_type || !PROCESSABLE_MIME.has(media.mime_type)) {
    return apiResponse(ctx, { ok: true, skipped: true, reason: `Media type ${media.mime_type ?? 'unknown'} is not processable` }, 200);
  }
  return apiResponse(ctx, {
    ok: true,
    variants_pending: true,
    message: media.storage
      ? 'Responsive image variants are generated on your build machine during the next publication.'
      : 'Responsive image variants are generated on your build machine during the next publication, after this image moves to your organization storage.',
  });
};
